using System;
class GroundWeaponChecks{
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}
 static void Main(){var w=new GroundWeaponState(0);Check(w.Drop(2,2,2)&&w.CenterX2==6&&w.CenterY2==6,"multi-cell center is exact");int paid=0;Func<bool> pay=()=>{paid++;return true;};Check(!w.PickUp(-1,2,2,1,true,true,()=>true,pay)&&paid==0,"other actor cannot claim weapon");Check(!w.PickUp(0,9,9,1,true,true,()=>true,pay)&&paid==0,"distant pickup spends nothing");Check(!w.PickUp(0,2,2,1,false,true,()=>true,pay)&&!w.PickUp(0,2,2,1,true,false,()=>true,pay),"consciousness and empty hand required");Check(!w.PickUp(0,2,2,1,true,true,()=>false,pay)&&paid==0,"overload consumes no interaction");Check(w.PickUp(0,2,2,1,true,true,()=>true,pay)&&paid==1&&!w.Dropped,"legal pickup consumes one interaction");Check(!w.PickUp(0,2,2,1,true,true,()=>true,pay)&&paid==1,"no duplicate pickup");w.Drop(0,0,1);Check(w.WithinReach(1,0,1)&&!w.WithinReach(1,1,1),"five-foot orthogonal reach, seven-foot diagonal excluded");w.Reset();Check(!w.Dropped,"reset clears ground state");w.Drop(2,2,1,true);int prior=paid;Check(!w.PickUp(0,2,2,1,true,true,()=>true,pay)&&paid==prior,"surface cannot pick up sunk weapon or spend resources");Check(w.PickUp(0,2,2,1,true,true,()=>true,pay,true),"submerged owner may retrieve sunk weapon");Console.WriteLine("PASS: ownership, centers, reach, hands, atomic resources and reset");}}
